CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles r JOIN public.staff_accounts s ON s.user_id=r.user_id WHERE r.user_id=_user_id AND r.role=_role AND s.active AND s.role='admin') $$;